    let es = 0; const ee = obj.modes.map(m => { const g = so.rePos ? Math.exp(R.g() * 0.45) : 1; const e = m.e * g * g * Math.pow(10, (softDb(m.f) + lim(m.f)) / 10); es += e; return e; });
