    const nt = useN ? S.clamp(p.ntau * Math.exp(R.g() * 0.25) * (tcSoft ? 1.6 : 1), 0.0003, 0.02) : 0, sh = Math.pow(2, dOct);
    const nspecAt = f => { const x = S.clamp(24 * Math.log2(f / sh / 100) / Math.log2(200) - 0.5, 0, 23), i = Math.min(22, Math.floor(x)), w = x - i; return p.nspec[i] * (1 - w) + p.nspec[i + 1] * w; };
    // 长时谱校色（参数域）：按"起始功率 × 衰减"解析算出合成结果的长时能量谱，和学到的长时平均谱（相对 fc）比，
    // 每个频带乘增益（±18dB 内、相邻平滑），主体/真模态/接触噪声一起乘 → 长时谱贴近同材质录音；不做整段 FFT，省时
    const G = new Float64Array(17).fill(1);
