    get measured() { return MEAS_CMB + '地面材质用学到的材质模型（草 = 沙土模型 + 高频草叶沙沙；浅水 = 简化水花：带通噪声中心频率上滑，设计约定；opts.richWater 时改用 C 线 splash）。设计约定：分段数、间隔、各层比例。'; },
    params: [
      { k: 'force', label: '力度', min: 0, max: 1, step: 0.05, def: 0.6 },
      { k: 'size', label: '体型', min: 0, max: 1, step: 0.05, def: 0.6 },
      { k: 'surface', label: '地面', options: Object.keys(SURF).map(k => [k, SURF_CN[k]]), def: 'stone' }
    ],
